<div class="patient-page-heading"><div><span class="eyebrow text-secondary">DISPONIBILIDAD INFORMATIVA</span><h1>Agenda semanal</h1><p class="text-secondary mb-0"><?= $escape($catalog['monday']->format('d/m/Y').'–'.$catalog['end']->format('d/m/Y')) ?> · America/La_Paz</p></div></div>
<?php require __DIR__.'/filters.php'; ?>
<div class="alert alert-light border"><strong>Consulta informativa; no realiza reservas.</strong> Ventana de referencia de diez días hábiles: <?= $escape($catalog['window'][0].' a '.$catalog['window'][9]) ?>. La gestión administrativa permite consultar otras semanas. Las franjas pasadas no se ofrecen como disponibles.</div>
<div class="schedule-legend"><span class="slot-disponible">Disponible</span><span class="slot-bloqueada">Bloqueada</span><span class="slot-ocupada">Ocupada</span><span class="slot-pasada">Pasada / no disponible</span></div>
<?php foreach($catalog['doctors'] as $m): ?><section class="patient-card mb-4" data-agenda-doctor="<?= $escape($m['id_medico']) ?>"><div class="schedule-card-heading"><h2 class="h5 mb-0"><?= $escape($m['nombres'].' '.$m['apellidos']) ?></h2><a href="/horarios/detalle?medico=<?= $escape($m['id_medico']) ?>">Horario habitual</a></div><div class="schedule-week">
<?php foreach($catalog['days'][(int)$m['id_medico']] ?? [] as $day): $date=\Clinica\Services\ScheduleValidator::date($day['fecha']); ?><article class="schedule-day"><h3><?= $escape(\Clinica\Services\ScheduleValidator::DAYS[(int)$date->format('N')] ?? ((int)$date->format('N')===6 ? 'Sábado' : 'Domingo')) ?><small><?= $escape($date->format('d/m')) ?></small></h3>
<?php foreach($day['horarios'] as $h): ?><p class="habitual-label">Habitual <?= $escape($h['hora_inicio'].'–'.$h['hora_fin']) ?></p><?php endforeach; ?>
<?php foreach($day['bloqueos'] as $b): ?><p class="schedule-event slot-bloqueada">Bloqueo <?= $escape($b['hora_inicio'].'–'.$b['hora_fin']) ?></p><?php endforeach; ?>
<?php foreach($day['citas'] as $c): ?><p class="schedule-event slot-ocupada">Cita ocupada <?= $escape($c['hora_inicio'].'–'.$c['hora_fin']) ?></p><?php endforeach; ?>
<?php foreach($day['franjas'] as $slot): $class=$slot['estado']==='disponible' ? 'slot-disponible' : (str_contains($slot['estado'],'ocupada') ? 'slot-ocupada' : ($slot['estado']==='bloqueada' ? 'slot-bloqueada' : 'slot-pasada')); ?><div class="schedule-slot <?= $class ?>" data-slot-state="<?= $escape($slot['estado']) ?>"><strong><?= $escape(\Clinica\Services\ScheduleValidator::displayTime($slot['hora_inicio']).'–'.\Clinica\Services\ScheduleValidator::displayTime($slot['hora_fin'])) ?></strong><span><?= $escape(ucfirst($slot['estado'])) ?></span><?php if(!$slot['dentro_ventana']): ?><small>Fuera de la ventana de referencia</small><?php endif; ?></div><?php endforeach; ?>
<?php if(!$day['horarios'] && !$day['bloqueos'] && !$day['citas']): ?><p class="text-secondary small">Sin atención configurada.</p><?php endif; ?></article><?php endforeach; ?></div></section><?php endforeach; ?>
<?php if(!$catalog['doctors']): ?><div class="patient-empty">No hay agendas dentro de su ámbito para estos filtros.</div><?php endif; ?>

